//! Declarative loose and indexed resource access. IDs generated by rules are slash-separated paths.
use globset::Glob;
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs::{self, File},
    io::{self, Read, Seek, SeekFrom, Write},
    path::{Path, PathBuf},
};

pub type Result<T> = std::result::Result<T, Box<dyn std::error::Error + Send + Sync>>;
fn invalid(s: impl Into<String>) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, s.into())
}
#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum Compression {
    None,
    Zstd,
    #[default]
    Auto,
}
#[derive(Debug, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct Package {
    pub target_size_mib: u64,
    pub default_compression: Compression,
    pub compression_level: i32,
}
impl Default for Package {
    fn default() -> Self {
        Self {
            target_size_mib: 64,
            default_compression: Compression::Auto,
            compression_level: 3,
        }
    }
}
#[derive(Debug, Deserialize, Default)]
#[serde(deny_unknown_fields)]
pub struct Policy {
    pub compression: Option<Compression>,
    pub compression_level: Option<i32>,
}
#[derive(Debug, Deserialize, Default)]
#[serde(deny_unknown_fields)]
pub struct Rule {
    pub pattern: String,
    #[serde(rename = "type")]
    pub kind: Option<String>,
    pub compression: Option<Compression>,
    pub compression_level: Option<i32>,
    #[serde(default)]
    pub dev_only: bool,
}
#[derive(Debug, Deserialize, Default)]
#[serde(deny_unknown_fields)]
pub struct Asset {
    pub id: String,
    pub path: String,
    #[serde(rename = "type")]
    pub kind: Option<String>,
    pub compression: Option<Compression>,
    pub compression_level: Option<i32>,
    #[serde(default)]
    pub dev_only: bool,
}
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Exclude {
    pub pattern: String,
}
#[derive(Debug, Deserialize, Default)]
#[serde(default, deny_unknown_fields)]
pub struct Manifest {
    pub package: Package,
    pub rules: Vec<Rule>,
    pub assets: Vec<Asset>,
    pub exclude: Vec<Exclude>,
    pub types: BTreeMap<String, Policy>,
}
#[derive(Clone, Debug)]
pub struct Resource {
    pub id: String,
    pub path: String,
    pub kind: String,
    pub compression: Compression,
    pub level: i32,
}
pub struct Catalogue {
    pub root: PathBuf,
    pub manifest: Manifest,
    pub entries: Vec<Resource>,
}
fn safe(root: &Path, path: &str) -> Result<PathBuf> {
    if path == ".resources"
        || path.is_empty()
        || path.contains('\\')
        || Path::new(path)
            .components()
            .any(|c| !matches!(c, std::path::Component::Normal(_)))
    {
        return Err(invalid(format!("invalid resource path: {path}")).into());
    }
    let resolved = root
        .join(path)
        .canonicalize()
        .map_err(|e| invalid(format!("resource {path}: {e}")))?;
    if !resolved.starts_with(root) || !resolved.is_file() {
        return Err(invalid(format!("resource escapes root or is not a file: {path}")).into());
    }
    Ok(resolved)
}
impl Catalogue {
    pub fn read(root: impl AsRef<Path>, release: bool) -> Result<Self> {
        let root = root.as_ref().canonicalize()?;
        let manifest: Manifest = toml::from_str(&fs::read_to_string(root.join(".resources"))?)?;
        if manifest.package.target_size_mib == 0
            || manifest.package.target_size_mib > u64::MAX / (1024 * 1024)
        {
            return Err(invalid("invalid target_size_mib").into());
        }
        for level in std::iter::once(Some(manifest.package.compression_level))
            .chain(manifest.types.values().map(|p| p.compression_level))
            .chain(manifest.rules.iter().map(|p| p.compression_level))
            .chain(manifest.assets.iter().map(|p| p.compression_level))
            .flatten()
        {
            if !(-7..=22).contains(&level) {
                return Err(invalid("zstd level must be -7..22").into());
            }
        }
        let rules = manifest
            .rules
            .iter()
            .map(|r| Glob::new(&r.pattern).map(|g| g.compile_matcher()))
            .collect::<std::result::Result<Vec<_>, _>>()?;
        let exclusions = manifest
            .exclude
            .iter()
            .map(|r| Glob::new(&r.pattern).map(|g| g.compile_matcher()))
            .collect::<std::result::Result<Vec<_>, _>>()?;
        let excluded = |p: &str| exclusions.iter().any(|g| g.is_match(p));
        let mut paths: BTreeMap<String, Resource> = BTreeMap::new();
        let make = |id: String,
                    path: String,
                    kind: Option<String>,
                    compression: Option<Compression>,
                    level: Option<i32>|
         -> Result<Resource> {
            if id.is_empty() || id.len() > 4096 {
                return Err(invalid("empty or oversized resource ID").into());
            }
            let kind = kind.unwrap_or_else(|| "binary".into());
            let policy = manifest.types.get(&kind);
            let level = level
                .or(policy.and_then(|p| p.compression_level))
                .unwrap_or(manifest.package.compression_level);
            if !(-7..=22).contains(&level) {
                return Err(invalid("zstd level must be -7..22").into());
            }
            Ok(Resource {
                id,
                path,
                kind,
                compression: compression
                    .or(policy.and_then(|p| p.compression))
                    .unwrap_or(manifest.package.default_compression),
                level,
            })
        };
        for file in walkdir::WalkDir::new(&root).follow_links(false) {
            let file = file?;
            if !file.file_type().is_file() && !file.file_type().is_symlink() {
                continue;
            }
            let path = file
                .path()
                .strip_prefix(&root)?
                .to_str()
                .ok_or_else(|| invalid("non UTF-8 resource path"))?
                .replace('\\', "/");
            if path == ".resources" || excluded(&path) {
                continue;
            }
            for (rule, glob) in manifest.rules.iter().zip(&rules) {
                if glob.is_match(&path) {
                    safe(&root, &path)?;
                    if release && rule.dev_only {
                        paths.remove(&path);
                    } else {
                        paths.insert(
                            path.clone(),
                            make(
                                path.clone(),
                                path.clone(),
                                rule.kind.clone(),
                                rule.compression,
                                rule.compression_level,
                            )?,
                        );
                    }
                }
            }
        }
        let mut explicit = BTreeSet::new();
        for a in &manifest.assets {
            if !explicit.insert(&a.id) {
                return Err(invalid(format!("duplicate resource ID: {}", a.id)).into());
            }
            safe(&root, &a.path)?;
            if excluded(&a.path) {
                return Err(invalid(format!("explicit resource is excluded: {}", a.path)).into());
            }
            let previous = paths.remove(&a.path);
            if !(release && a.dev_only) {
                let resource = make(
                    a.id.clone(),
                    a.path.clone(),
                    a.kind
                        .clone()
                        .or_else(|| previous.as_ref().map(|p| p.kind.clone())),
                    a.compression
                        .or_else(|| previous.as_ref().map(|p| p.compression)),
                    a.compression_level
                        .or_else(|| previous.as_ref().map(|p| p.level)),
                )?;
                let key = format!("\0{}", a.id);
                if paths.insert(key, resource).is_some() {
                    return Err(invalid("duplicate explicit resource").into());
                }
            }
        }
        let mut entries: Vec<_> = paths.into_values().collect();
        entries.sort_by(|a, b| a.id.cmp(&b.id));
        for pair in entries.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(invalid(format!("duplicate resource ID: {}", pair[0].id)).into());
            }
        }
        Ok(Self {
            root,
            manifest,
            entries,
        })
    }
    pub fn copy_loose(&self, destination: &Path) -> Result<()> {
        fs::create_dir_all(destination)?;
        // Copy only catalogued resources; flatten the effective catalogue into an authoritative manifest.
        let mut text = String::new();
        for e in &self.entries {
            let out = destination.join(&e.path);
            fs::create_dir_all(out.parent().unwrap())?;
            fs::copy(safe(&self.root, &e.path)?, out)?;
            text.push_str(&format!(
                "[[assets]]\nid = {}\npath = {}\ntype = {}\n",
                toml::Value::String(e.id.clone()),
                toml::Value::String(e.path.clone()),
                toml::Value::String(e.kind.clone())
            ));
        }
        fs::write(destination.join(".resources"), text)?;
        Ok(())
    }
    pub fn pack(&self, destination: &Path) -> Result<()> {
        self.pack_with_limit(
            destination,
            self.manifest.package.target_size_mib * 1024 * 1024,
        )
    }
    fn pack_with_limit(&self, destination: &Path, limit: u64) -> Result<()> {
        fs::create_dir_all(destination)?;
        // Spool one asset at a time to bound memory; the index lives in container zero.
        let mut entries = Vec::new();
        for e in &self.entries {
            entries.push(IndexEntry {
                id: e.id.clone(),
                kind: e.kind.clone(),
                container: 0,
                offset: 0,
                stored: 0,
                original: 0,
                compressed: false,
            });
        }
        let index_size = bincode::serialized_size(&entries)?;
        if index_size > 64 * 1024 * 1024 {
            return Err(invalid("resource index exceeds 64 MiB").into());
        }
        let mut container = 0u32;
        let mut offset = 16 + index_size;
        let mut file = File::create(destination.join("00000000.resource"))?;
        file.seek(SeekFrom::Start(offset))?;
        for (e, index) in self.entries.iter().zip(&mut entries) {
            let bytes = fs::read(safe(&self.root, &e.path)?)?;
            index.original = bytes.len() as u64;
            let already = matches!(
                Path::new(&e.path).extension().and_then(|s| s.to_str()),
                Some("png" | "jpg" | "jpeg" | "ogg" | "opus" | "zip")
            );
            let compressed = if e.compression == Compression::Zstd
                || (e.compression == Compression::Auto && !already)
            {
                Some(zstd::bulk::compress(&bytes, e.level)?)
            } else {
                None
            };
            let data = if let Some(c) = compressed.as_ref().filter(|c| {
                e.compression == Compression::Zstd || c.len() + 32 < bytes.len() * 95 / 100
            }) {
                index.compressed = true;
                c.as_slice()
            } else {
                &bytes
            };
            let length = data.len() as u64;
            if offset
                .checked_add(length)
                .ok_or_else(|| invalid("package size overflow"))?
                > limit
                && offset > 0
            {
                container = container
                    .checked_add(1)
                    .ok_or_else(|| invalid("too many containers"))?;
                offset = 0;
                file = File::create(destination.join(format!("{container:08}.resource")))?;
            }
            index.container = container;
            index.offset = offset;
            index.stored = length;
            file.write_all(data)?;
            offset += length;
        }
        let mut first = File::options()
            .write(true)
            .open(destination.join("00000000.resource"))?;
        first.write_all(b"DOGWOOD\0")?;
        first.write_all(&index_size.to_le_bytes())?;
        bincode::serialize_into(first, &entries)?;
        Ok(())
    }
}
#[derive(Debug, Serialize, Deserialize)]
struct IndexEntry {
    id: String,
    kind: String,
    container: u32,
    offset: u64,
    stored: u64,
    original: u64,
    compressed: bool,
}
/// Seekable resource with reads restricted to its own byte range.
pub struct ResourceReader {
    inner: Reader,
    length: u64,
    position: u64,
}
enum Reader {
    File(File, u64),
    Memory(io::Cursor<Vec<u8>>),
}
impl Read for ResourceReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let count = buf
            .len()
            .min((self.length - self.position).min(usize::MAX as u64) as usize);
        let n = match &mut self.inner {
            Reader::File(f, _) => f.read(&mut buf[..count])?,
            Reader::Memory(c) => c.read(&mut buf[..count])?,
        };
        if n == 0 && count > 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "truncated resource",
            ));
        }
        self.position += n as u64;
        Ok(n)
    }
}
impl Seek for ResourceReader {
    fn seek(&mut self, from: SeekFrom) -> io::Result<u64> {
        let p = match from {
            SeekFrom::Start(p) => p as i128,
            SeekFrom::Current(p) => self.position as i128 + p as i128,
            SeekFrom::End(p) => self.length as i128 + p as i128,
        };
        if p < 0 || p > self.length as i128 {
            return Err(invalid("seek outside resource"));
        }
        self.position = p as u64;
        match &mut self.inner {
            Reader::File(f, start) => {
                f.seek(SeekFrom::Start(*start + self.position))?;
            }
            Reader::Memory(c) => {
                c.set_position(self.position);
            }
        }
        Ok(self.position)
    }
}
enum Backend {
    Loose(Catalogue),
    Packed {
        root: PathBuf,
        index: BTreeMap<String, IndexEntry>,
    },
}
pub struct Resources {
    backend: Backend,
}
impl Resources {
    pub fn loose(root: impl AsRef<Path>) -> Result<Self> {
        Ok(Self {
            backend: Backend::Loose(Catalogue::read(root, false)?),
        })
    }
    pub fn packaged(root: impl AsRef<Path>) -> Result<Self> {
        use bincode::Options;
        let root = root.as_ref().to_owned();
        let mut file = File::open(root.join("00000000.resource"))?;
        let mut header = [0; 16];
        file.read_exact(&mut header)?;
        if &header[..8] != b"DOGWOOD\0" {
            return Err(invalid("invalid Dogwood resource signature").into());
        }
        let length = u64::from_le_bytes(header[8..].try_into()?);
        if length > 64 * 1024 * 1024 || length > file.metadata()?.len().saturating_sub(16) {
            return Err(invalid("invalid resource index size").into());
        }
        let entries: Vec<IndexEntry> = bincode::DefaultOptions::new()
            .with_fixint_encoding()
            .with_limit(length)
            .reject_trailing_bytes()
            .deserialize_from(file.take(length))?;
        let mut index = BTreeMap::new();
        let mut files = BTreeMap::new();
        let mut ends = BTreeMap::new();
        for e in entries {
            if e.id.is_empty()
                || (!e.compressed && e.stored != e.original)
                || e.container == 0 && e.offset < 16 + length
            {
                return Err(invalid("invalid resource index entry").into());
            }
            let f = match files.entry(e.container) {
                std::collections::btree_map::Entry::Vacant(v) => v.insert(File::open(
                    root.join(format!("{:08}.resource", e.container)),
                )?),
                std::collections::btree_map::Entry::Occupied(o) => o.into_mut(),
            };
            let end = e
                .offset
                .checked_add(e.stored)
                .ok_or_else(|| invalid("resource range overflow"))?;
            if end > f.metadata()?.len() || e.offset < *ends.get(&e.container).unwrap_or(&0) {
                return Err(invalid("truncated or overlapping resource range").into());
            }
            ends.insert(e.container, end);
            if index.insert(e.id.clone(), e).is_some() {
                return Err(invalid("duplicate index ID").into());
            }
        }
        Ok(Self {
            backend: Backend::Packed { root, index },
        })
    }
    /// Discover distributions relative to the executable, with an explicit source root for development.
    pub fn discover(development_root: impl AsRef<Path>) -> Result<Self> {
        if let Some(root) = std::env::var_os("DOGWOOD_ASSET_ROOT") {
            return Self::loose(PathBuf::from(root));
        }
        let exe = std::env::current_exe()?;
        let dir = exe
            .parent()
            .ok_or_else(|| invalid("executable has no parent"))?;
        for base in [dir.to_owned(), dir.join("../Resources")] {
            if base.join("resources/00000000.resource").is_file() {
                return Self::packaged(base.join("resources"));
            }
            if base.join("assets/.resources").is_file() {
                return Self::loose(base.join("assets"));
            }
        }
        if cfg!(debug_assertions) {
            return Self::loose(development_root);
        }
        Err(invalid("no resources beside executable (or in app Resources)").into())
    }
    pub fn ids(&self) -> Vec<&str> {
        match &self.backend {
            Backend::Loose(c) => c.entries.iter().map(|e| e.id.as_str()).collect(),
            Backend::Packed { index, .. } => index.keys().map(String::as_str).collect(),
        }
    }
    pub fn open(&self, id: &str) -> Result<ResourceReader> {
        match &self.backend {
            Backend::Loose(c) => {
                let e = c
                    .entries
                    .binary_search_by(|e| e.id.as_str().cmp(id))
                    .map_err(|_| invalid(format!("missing resource: {id}")))?;
                let f = File::open(safe(&c.root, &c.entries[e].path)?)?;
                let length = f.metadata()?.len();
                Ok(ResourceReader {
                    inner: Reader::File(f, 0),
                    length,
                    position: 0,
                })
            }
            Backend::Packed { index, root } => {
                let e = index.get(id).ok_or_else(|| {
                    invalid(format!("missing resource {id} in {}", root.display()))
                })?;
                // Open independent handles: cloned OS handles share seek positions on Unix.
                let mut f = File::open(root.join(format!("{:08}.resource", e.container)))?;
                f.seek(SeekFrom::Start(e.offset))?;
                if e.compressed {
                    let mut decoder = zstd::stream::read::Decoder::new(f.take(e.stored))?;
                    let mut bytes = Vec::new();
                    decoder
                        .by_ref()
                        .take(
                            e.original
                                .checked_add(1)
                                .ok_or_else(|| invalid("resource size overflow"))?,
                        )
                        .read_to_end(&mut bytes)?;
                    if bytes.len() as u64 != e.original {
                        return Err(invalid("decompressed resource size mismatch").into());
                    }
                    Ok(ResourceReader {
                        inner: Reader::Memory(io::Cursor::new(bytes)),
                        length: e.original,
                        position: 0,
                    })
                } else {
                    Ok(ResourceReader {
                        inner: Reader::File(f, e.offset),
                        length: e.original,
                        position: 0,
                    })
                }
            }
        }
    }
    pub fn load(&self, id: &str) -> Result<Vec<u8>> {
        let mut bytes = Vec::new();
        self.open(id)?.read_to_end(&mut bytes)?;
        Ok(bytes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    fn fixture(text: &str) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join(".resources"), text).unwrap();
        dir
    }
    #[test]
    fn catalogue_rules_overrides_exclusions_and_development() {
        let dir = fixture(
            r#"
            [[rules]]
            pattern = "*.txt"
            type = "text"
            [[assets]]
            id = "stable"
            path = "a.txt"
            compression = "none"
            [[assets]]
            id = "debug"
            path = "debug.bin"
            dev_only = true
            [[exclude]]
            pattern = "ignored*"
        "#,
        );
        for p in ["a.txt", "b.txt", "debug.bin", "ignored.txt"] {
            fs::write(dir.path().join(p), p).unwrap();
        }
        let dev = Catalogue::read(dir.path(), false).unwrap();
        assert_eq!(dev.entries.len(), 3);
        let release = Catalogue::read(dir.path(), true).unwrap();
        assert_eq!(release.entries.len(), 2);
        assert_eq!(release.entries[1].id, "stable");
        assert_eq!(release.entries[1].compression, Compression::None);
        let out = tempfile::tempdir().unwrap();
        dev.copy_loose(out.path()).unwrap();
        assert!(!out.path().join("ignored.txt").exists());
        assert_eq!(
            Resources::loose(out.path())
                .unwrap()
                .load("stable")
                .unwrap(),
            b"a.txt"
        );
    }
    #[test]
    fn invalid_catalogues_fail() {
        for manifest in [
            "nonsense = 2",
            "[package]\ntarget_size_mib = 0",
            "[[assets]]\nid='a'\npath='missing'",
            "[[assets]]\nid='a'\npath='../escape'",
            "[[rules]]\npattern='['",
        ] {
            let dir = fixture(manifest);
            assert!(Catalogue::read(dir.path(), true).is_err(), "{manifest}");
        }
        let dir = fixture("[[assets]]\nid='same'\npath='a'\n[[assets]]\nid='same'\npath='b'");
        fs::write(dir.path().join("a"), b"a").unwrap();
        fs::write(dir.path().join("b"), b"b").unwrap();
        assert!(Catalogue::read(dir.path(), false).is_err());
    }
    #[test]
    fn roundtrip_determinism_boundaries_compression_and_corruption() {
        let dir = fixture(
            r#"
            [[rules]]
            pattern = "*"
            [[assets]]
            id = "a"
            path = "a"
            compression = "none"
            [[assets]]
            id = "b"
            path = "b"
            compression = "zstd"
        "#,
        );
        for (name, bytes) in [
            ("a", vec![1; 700]),
            ("b", vec![2; 5000]),
            ("c", vec![3; 9000]),
            ("d", (0..2000).map(|i| (i * 73 % 251) as u8).collect()),
        ] {
            fs::write(dir.path().join(name), bytes).unwrap();
        }
        let catalogue = Catalogue::read(dir.path(), true).unwrap();
        let a = tempfile::tempdir().unwrap();
        let b = tempfile::tempdir().unwrap();
        catalogue.pack_with_limit(a.path(), 512).unwrap();
        catalogue.pack_with_limit(b.path(), 512).unwrap();
        let packaged = Resources::packaged(a.path()).unwrap();
        let loose = Resources::loose(dir.path()).unwrap();
        for id in loose.ids() {
            assert_eq!(loose.load(id).unwrap(), packaged.load(id).unwrap());
        }
        let Backend::Packed { index, .. } = &packaged.backend else {
            panic!()
        };
        assert!(!index["a"].compressed);
        assert!(index["b"].compressed);
        assert!(index["c"].compressed);
        assert!(index.values().any(|e| e.container > 0));
        for e in index.values() {
            assert!(
                e.offset + e.stored
                    <= fs::metadata(a.path().join(format!("{:08}.resource", e.container)))
                        .unwrap()
                        .len()
            );
        }
        for entry in fs::read_dir(a.path()).unwrap() {
            let entry = entry.unwrap();
            assert_eq!(
                fs::read(entry.path()).unwrap(),
                fs::read(b.path().join(entry.file_name())).unwrap()
            );
        }
        let mut reader = packaged.open("a").unwrap();
        reader.seek(SeekFrom::End(-2)).unwrap();
        let mut tail = Vec::new();
        reader.read_to_end(&mut tail).unwrap();
        assert_eq!(tail, vec![1; 2]);
        assert!(reader.seek(SeekFrom::End(1)).is_err());
        assert!(packaged.load("missing").is_err());
        let container = a
            .path()
            .join(format!("{:08}.resource", index["a"].container));
        File::options()
            .write(true)
            .open(container)
            .unwrap()
            .set_len(1)
            .unwrap();
        assert!(Resources::packaged(a.path()).is_err());
        fs::write(b.path().join("00000000.resource"), b"corrupt").unwrap();
        assert!(Resources::packaged(b.path()).is_err());
    }
    #[test]
    fn symlink_escape_fails() {
        #[cfg(unix)]
        {
            let dir = fixture("[[assets]]\nid='escape'\npath='link'");
            let outside = tempfile::NamedTempFile::new().unwrap();
            std::os::unix::fs::symlink(outside.path(), dir.path().join("link")).unwrap();
            assert!(Catalogue::read(dir.path(), false).is_err());
        }
    }
    #[test]
    fn type_policy_auto_rejection_and_damaged_compression() {
        let dir = fixture(
            r#"
            [types.text]
            compression="zstd"
            compression_level=5
            [[rules]]
            pattern="*"
            type="text"
            [[assets]]
            id="text"
            path="text"
            [[assets]]
            id="noise"
            path="noise"
            compression="auto"
        "#,
        );
        fs::write(dir.path().join("text"), vec![42; 8192]).unwrap();
        let mut seed = 91u32;
        let noise: Vec<_> = (0..8192)
            .map(|_| {
                seed ^= seed << 13;
                seed ^= seed >> 17;
                seed ^= seed << 5;
                seed as u8
            })
            .collect();
        fs::write(dir.path().join("noise"), &noise).unwrap();
        let c = Catalogue::read(dir.path(), true).unwrap();
        assert_eq!(c.entries[1].kind, "text");
        assert_eq!(c.entries[1].level, 5);
        let out = tempfile::tempdir().unwrap();
        c.pack(out.path()).unwrap();
        let r = Resources::packaged(out.path()).unwrap();
        assert_eq!(r.load("noise").unwrap(), noise);
        let Backend::Packed { index, .. } = &r.backend else {
            panic!()
        };
        assert!(!index["noise"].compressed);
        assert!(index["text"].compressed);
        let e = &index["text"];
        let mut f = File::options()
            .write(true)
            .open(out.path().join(format!("{:08}.resource", e.container)))
            .unwrap();
        f.seek(SeekFrom::Start(e.offset)).unwrap();
        f.write_all(&vec![0; e.stored as usize]).unwrap();
        assert!(r.load("text").is_err());
    }
}
